# The frontend image's nginx.conf proxies to the compose host name `backend`.
# In the Container App the API is another container of the same replica, so
# the upstream is 127.0.0.1 (no DNS), and nginx listens on 8080 unprivileged.
# Mounted over /etc/nginx/conf.d from a Container Apps secret (main.bicep).
server {
    listen 8080;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    # Stock mime.types lacks .mjs (the pdf.js worker); see frontend/nginx.conf.
    include /etc/nginx/mime.types;
    types {
        text/javascript mjs;
    }
    include /etc/nginx/security-headers.conf;

    location /api/ {
        proxy_pass http://127.0.0.1:8000/api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 300s;
    }

    location /assets/ {
        include /etc/nginx/security-headers.conf;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        try_files $uri =404;
    }

    location / {
        include /etc/nginx/security-headers.conf;
        add_header Cache-Control "no-cache" always;
        try_files $uri $uri/ /index.html;
    }

    gzip on;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml image/svg+xml;
    gzip_min_length 1024;
}
